import os
import torch


class Config:
    # ==== General Configuration ====
    PROJECT_NAME = "audio_tagging_idea_2"
    SEED = 42
    # 12 vCPUs available, leaving some overhead
    NUM_WORKERS = 8
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # ==== Paths ====
    INPUT_ROOT = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the provided script
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Output directories
    WORKING_DIR = "./working/idea_2"
    SAVE_DIR = WORKING_DIR  # Where models/checkpoints are saved
    SUBMISSION_PATH = "./submission/submission.csv"

    # Ensure working directory exists
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(os.path.dirname(SUBMISSION_PATH), exist_ok=True)

    # ==== Audio Processing ====
    SAMPLE_RATE = 32000
    # Training duration in seconds (random crop/pad).
    # Mean duration is ~13s, max 30s. 10s is a good trade-off for batching.
    TRAIN_DURATION = 10.0
    N_MELS = 128
    N_FFT = 1024
    HOP_LENGTH = 320
    FMIN = 0
    FMAX = None  # Defaults to SAMPLE_RATE // 2

    # ==== Model Architecture ====
    MODEL_NAME = "mobilenetv2_100"
    NUM_CLASSES = 80
    IN_CHANNELS = 1
    # Use ImageNet weights
    PRETRAINED = True
    # Head type: 'attention' (Attention Pooling), 'avg' (Global Average), or 'max' (Global Max)
    POOLING_TYPE = "max"

    # ==== Training Hyperparameters ====
    BATCH_SIZE = 64
    MAX_EPOCHS = 50
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-2  # Standard for AdamW

    # Optimizer & Scheduler
    OPTIMIZER = "AdamW"
    SCHEDULER = "CosineAnnealingLR"
    # Cosine Annealing parameters
    T_MAX = MAX_EPOCHS  # Cycle length matches max epochs
    ETA_MIN = 1e-6  # Minimum learning rate

    # Early Stopping
    EARLY_STOPPING_PATIENCE = 10

    # ==== Augmentation ====
    # Mixup
    USE_MIXUP = True
    MIXUP_ALPHA = 1.0  # Uniform distribution

    # SpecAugment
    USE_SPEC_AUGMENT = True
    SPEC_AUG_FREQ_MASK = 30
    SPEC_AUG_TIME_MASK = 30

    # Normalization
    # "Instance-wise normalization (zero mean, unit variance)"
    NORMALIZE_INSTANCE = True

    # ==== Debugging ====
    # If True, runs on a small subset of data for quick pipeline verification
    DEBUG = False
    DEBUG_SUBSET_SIZE = 100
